def is_valid_roman_numeral(s):
    import re
    if not s:
        return False
    pattern = r'M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})'
    return re.fullmatch(pattern, s) is not None

def is_valid_hex_string_even_length(s):
    if not s or len(s) % 2 != 0:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s)

def is_valid_base64_format(s):
    if not s or len(s) % 4 != 0:
        return False
    if s.count('=') > 2:
        return False
    core = s.rstrip('=')
    if '=' in core:
        return False
    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    return all(c in alphabet for c in core)

def is_valid_variable_declaration(s):
    parts = s.split(' ')
    if len(parts) != 2:
        return False
    typ, name = parts
    if typ not in {'int', 'float', 'str', 'bool'}:
        return False
    if not name or not (name[0].isalpha() or name[0] == '_'):
        return False
    return all(c.isalnum() or c == '_' for c in name)

def is_valid_camel_case(s):
    if not s or not (s[0].isalpha() and s[0].islower()):
        return False
    return all(c.isalnum() for c in s)

def is_valid_snake_case(s):
    if not s or not (s[0].isalpha() and s[0].islower()):
        return False
    if s.endswith('_'):
        return False
    if '__' in s:
        return False
    return all((c.isalpha() and c.islower()) or c.isdigit() or c == '_' for c in s)

def is_valid_us_zip_code(s):
    if len(s) == 5 and s.isdigit():
        return True
    if len(s) == 10 and s[5] == '-' and s[:5].isdigit() and s[6:].isdigit():
        return True
    return False

def is_valid_canadian_postal_code(s):
    if len(s) != 7 or s[3] != ' ':
        return False
    a, b, c, d, e, f = s[0], s[1], s[2], s[4], s[5], s[6]
    return (a.isalpha() and a.isupper() and b.isdigit() and c.isalpha() and c.isupper()
            and d.isdigit() and e.isalpha() and e.isupper() and f.isdigit())

def is_valid_uk_postcode_simplified(s):
    if s.count(' ') != 1:
        return False
    outward, inward = s.split(' ')
    if not (2 <= len(outward) <= 4):
        return False
    if not outward[0].isalpha() or not outward.isalnum():
        return False
    if len(inward) != 3:
        return False
    return inward[0].isdigit() and inward[1].isalpha() and inward[2].isalpha()

def is_valid_us_phone_number(s):
    if len(s) != 14:
        return False
    if s[0] != '(' or s[4] != ')' or s[5] != ' ' or s[9] != '-':
        return False
    area, mid, last = s[1:4], s[6:9], s[10:14]
    if not (area.isdigit() and mid.isdigit() and last.isdigit()):
        return False
    return area[0] in '23456789'

def is_valid_dashed_phone_number(s):
    parts = s.split('-')
    if len(parts) != 3:
        return False
    a, b, c = parts
    if not (len(a) == 3 and a.isdigit() and len(b) == 3 and b.isdigit() and len(c) == 4 and c.isdigit()):
        return False
    return a[0] in '23456789'

def is_valid_e164_phone_number(s):
    if not s.startswith('+'):
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if not (8 <= len(digits) <= 15):
        return False
    return digits[0] != '0'

def is_valid_grid_reference(s):
    if len(s) < 2:
        return False
    if not s[0].isalpha() or not s[0].isupper():
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if len(digits) > 1 and digits[0] == '0':
        return False
    return 1 <= int(digits) <= 99

def is_valid_sudoku_row(row):
    if len(row) != 9:
        return False
    seen = set()
    for x in row:
        if x == 0:
            continue
        if not (1 <= x <= 9):
            return False
        if x in seen:
            return False
        seen.add(x)
    return True

def is_valid_sudoku_box(box):
    if len(box) != 9:
        return False
    seen = set()
    for x in box:
        if x == 0:
            continue
        if not (1 <= x <= 9):
            return False
        if x in seen:
            return False
        seen.add(x)
    return True

def is_symmetric_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            if m[i][j] != m[j][i]:
                return False
    return True

def is_valid_matrix_shape(m, rows, cols):
    if len(m) != rows:
        return False
    return all(len(r) == cols for r in m)
